class PuzzleFileError : public std::runtime_error { // starts the error class, which inherits from runtime_error so it carries a message
public: // everything below this label can be used from outside the class
    explicit PuzzleFileError(const std::string& message) : std::runtime_error(message) {} // constructor that passes the message up to the base class
}; //End of PuzzleFileError

// Holds a 9x9 board and knows the Sudoku rules. It has no solving strategy.

//===============================
// SudokuGrid: stores the 9x9 board and knows the Sudoku rules.
//It does not contain any solving strategy; that lives in SudokuSolver.
//===============================

class SudokuGrid { // starts the class that represents the board
public: //members below are public interface
    static constexpr int kSize = 9;   // the board is 9 cells wide and 9 cells tall
    static constexpr int kBlockSize = 3;  // each block is 3 cells wide and 3 cells tall
    static constexpr int kEmpty = 0;  // 0 is the value that means "this cell is blank"

    SudokuGrid() { // constructor: runs when a new grid is created
        for (auto& row : cells_) row.fill(kEmpty);  // set every cell in every row to blank
    } //End of SudokuGrid

    int  valueAt(int row, int col) const { return cells_[row][col]; } // returns digits stored at this cell 
    void setValue(int row, int col, int digit) { cells_[row][col] = digit; } // store a digit in this cell
    void clearCell(int row, int col) { cells_[row][col] = kEmpty; } //make cell blank when backtracking
    bool isEmptyAt(int row, int col) const { return cells_[row][col] == kEmpty; } //true if this cell is blank

    // Looks for an empty cell starting at startIndex (0-80, row by row).
    // Cells before startIndex are never checked again. Returns false if none is left.
    bool findEmptyCellFrom(int startIndex, int& row, int& col) const { //starts the function: row and col are outputs
        for (int index = startIndex; index < kSize * kSize; ++index) { //walk through the cells from startIndex to the last cell
            row = index / kSize; //convert the index to a row number
            col = index % kSize; // convert the index to a column number
            if (isEmptyAt(row, col)) return true; // stop at the first blank cell found
        } // ends the loop over cells
        return false; // no blank cells remain, so the grid is full
    } //End of findEmptyCellFrom

    // Digits 1-9 that are not already in this cell's row, column, or block.
    std::vector<int> candidatesFor(int row, int col) const { // starts the function that lists allowed digits
        std::array<bool, kSize + 1> used{}; // used[d] becomes true if digit d is already taken (index 0 stands for blanks)
        for (int i = 0; i < kSize; ++i) { // go through the 9 positions of this cell's row and column
            used[cells_[row][i]] = true; // mark the digit found in the same row
            used[cells_[i][col]] = true; // mark the digit found in the same column
        }
        const int blockRow = (row / kBlockSize) * kBlockSize; // top row of the block containing this cell
        const int blockCol = (col / kBlockSize) * kBlockSize; // left column of the block containing this cell
        for (int r = 0; r < kBlockSize; ++r)   // go through the 3 rows of the block
            for (int c = 0; c < kBlockSize; ++c) // go through the 3 columns of the block
                used[cells_[blockRow + r][blockCol + c]] = true;  // mark the digit found in the same block

        std::vector<int> candidates;  // list that will hold the allowed digits
        for (int digit = 1; digit <= kSize; ++digit) // check each digit from 1 to 9
            if (!used[digit]) candidates.push_back(digit);   // keep the digit if nothing has used it
        return candidates;   // an empty list means this cell has no legal digit
    } //End of candidatesFor

    // True if no digit repeats in any row, column, or block (blanks are ignored).
    bool hasNoConflicts() const { //starts the conflict check
        for (int i = 0; i < kSize; ++i) { // i is the row, column, and block number, all from 0 to 8
            if (hasDuplicate(rowDigits(i)) || hasDuplicate(columnDigits(i)) || // does row i or column i repeat a digit?
                hasDuplicate(blockDigits(i))) // does block i repeat a digit?
                return false; // a repeat was found, so the clues conflict
        } // ends the loop over rows, columns, and blocks
        return true; // nothing repeated anywhere
    } //End of hasNoConflicts

    // One row per line, "|" between blocks, a dashed line between block rows.
    std::string toReadableString() const { //function that formats the grid
        std::ostringstream out; //buffer the collects the text
        for (int row = 0; row < kSize; ++row) { //go through each row
            if (row > 0 && row % kBlockSize == 0) out << "------+-------+------\n"; //dash lines for row 3 and 6
            for (int col = 0; col < kSize; ++col) { //go through each column of this row
                if (col > 0) out << (col % kBlockSize == 0 ? " | " : " "); //"|" before column 3 and 6, else a space
                out << (isEmptyAt(row, col) ? '_' : static_cast<char>('0' + cells_[row][col])); //print "_" for blankes; otherwise, digits
            }//end loop of column 
            out << '\n'; //end teh row
        } //end loop over rows
        return out.str(); // hand back the finished text 
    } //End of toReadableString

private: //helpers below are only used within the class
    std::vector<int> rowDigits(int row) const { //start row copy helper
        return std::vector<int>(cells_[row].begin(), cells_[row].end()); //builds a vector form the row's 9 values
    } //End of rowDigits
    std::vector<int> columnDigits(int col) const { //opens the column-copy helper
        std::vector<int> digits; //will hold the 9 values
        for (int r = 0; r < kSize; ++r) digits.push_back(cells_[r][col]); //takes ONE vlaue from each row
        return digits; //returns the column value
    }  //End of columnDigits

    std::vector<int> blockDigits(int blockIndex) const { //starts the block-copy helper
        std::vector<int> digits;//will hold the 9 value
        const int startRow = (blockIndex / kBlockSize) * kBlockSize;//frist row of this block
        const int startCol = (blockIndex % kBlockSize) * kBlockSize; //frist column of this block
        for (int r = 0; r < kBlockSize; ++r)// go through the black's 3 rows
            for (int c = 0; c < kBlockSize; ++c) digits.push_back(cells_[startRow + r][startCol + c]); //add each cell's value / go through the black's 3 columns
        return digits; //returns the block value 
    }  //End of blockDigits

    static bool hasDuplicate(const std::vector<int>& digits) { //begins the repeat checker
        std::array<bool, kSize + 1> seen{}; //seen[d] is true once digit d has been met
        for (int d : digits) { //look at each value of the list
            if (d == kEmpty) continue; //blanks can repeat, so skip them
            if (seen[d]) return true;// digit was already seen so it repeats
            seen[d] = true; //remember we've seen this digit
        } //ends teh loop over value
        return false; //no digits repeated 
    } //End of hasDuplicate

    std::array<std::array<int, kSize>, kSize> cells_; // 9x9 table of digits; 0 = blank
}; //End of SudokuGrid


//===============================
// PuzzleFileReader: turns text file into SudokiGrid, or will throws a PuzzleFileError with a CLEAR message (no crash)
//File MUST be 81 cell symbols and whitespace is ignored.
//===============================


// Turns a text file into a SudokuGrid, or throws PuzzleFileError with a message.
// Whitespace between cells is ignored; exactly 81 symbols (1-9 or '_') are required.
class PuzzleFileReader { //starts the file read class
public: //read function is public interface
    SudokuGrid read(const std::string& fileName) const { //starts the read. Takes teh file name and returns a grid
        std::ifstream input(fileName); //try to open the file
        if (!input) throw PuzzleFileError("Cannot open file (missing or unreadable).");//reporst missing file instead of crash

        const int cellCount = SudokuGrid::kSize * SudokuGrid::kSize; //full grid is 81 cells
        std::string symbols; //In the order they appear collect the cell characters
        char ch; //current character is being read
        while (input.get(ch)) { //read ONE character at a time UNTIL the file ends
            if (std::isspace(static_cast<unsigned char>(ch))) continue; //skip spaces, tabs, and line brekas
            if (!isValidSymbol(ch)) //anything other than "_" or 1 to 9 
                throw PuzzleFileError(std::string("Unexpected character '") + ch + //start building the error message with BAD characters
                                      "'; only digits 1-9 and '_' are allowed."); //finish error message then throw it
            symbols.push_back(ch); //keep valid symbol
            if (static_cast<int>(symbols.size()) > cellCount)//more than 81 symbols then file is tooo big
                throw PuzzleFileError("Too many cells; expected exactly 81.");//reports problem
        }//ends character reading loop
        if (input.bad()) throw PuzzleFileError("Error while reading file."); //a low-level read failure occurs
        if (static_cast<int>(symbols.size()) != cellCount) //less than 81 symbols the files is too small
            throw PuzzleFileError("Expected 81 cells but found " + std::to_string(symbols.size()) + "."); //declares how many were found

        SudokuGrid grid; //starts with all blank grids 
        for (int i = 0; i < cellCount; ++i) { //goes through the 81 symbols IN ORDER
            if (symbols[i] != '_') // blanks stored as 0's so only digits need to be stored 
                grid.setValue(i / SudokuGrid::kSize, i % SudokuGrid::kSize, symbols[i] - '0'); //coverts: index --> row/column and character --> numbers
        }// ends the loop filling in the grid
        return grid; //returns finished grid
    } //ends read

private: //helpers below are only used INSIDE this class 
    static bool isValidSymbol(char ch) { return ch == '_' || (ch >= '1' && ch <= '9'); } // accepts: "_" or an character 1 to 9
};  //End of PuzzleFileReader

//===============================
// SudokuSolver: Collects EVERY solution by recurive backtracking
//===============================

// Recursive backtracking search that collects every solution.
class SudokuSolver { //opens SudokuSolver
public: // findAllSolutions is public 
    std::vector<SudokuGrid> findAllSolutions(const SudokuGrid& puzzle) { //start of the function the begins the search
        solutions_.clear(); //FORGET any solutions from pervious puzzles
        if (!puzzle.hasNoConflicts()) return solutions_;  // given clues already break the rules
        SudokuGrid working = puzzle; //will search on a COPY so the original remains untouched
        search(working, 0); //begins the recursive search from the first cell
        return solutions_; //returns EVERYTHING that is found
    } //ends findAllSolutions

private: // the recurive and the stored solution are internal
    // startIndex is where the scan for an empty cell begins, so cells that were
    // already passed are not rescanned at every step.
    void search(SudokuGrid& grid, int startIndex) { //opens the recursive function
        int row = 0, col = 0; //recieves the position of the next blank cell
        if (!grid.findEmptyCellFrom(startIndex, row, col)) {  // no blanks left: solution
            solutions_.push_back(grid); //will save teh copy of the finish grid
            return; //will go back and try other possibilities 
        }// end the base case
        for (int digit : grid.candidatesFor(row, col)) {  // no candidates: loop skipped, backtrack
            grid.setValue(row, col, digit); //place the digit
            search(grid, row * SudokuGrid::kSize + col + 1); //recurse, continuing the scan just after this cell 
            grid.clearCell(row, col); //takes digit out so it can try the next candidates
        } //end loop over candidates
    } //end search

    std::vector<SudokuGrid> solutions_; //every solution found SO FAR
};  //End of SudokuSolver

//===============================
// PuzzleReporter: formates and prints the puzzle results 
//===============================


// Formats and prints the results for one puzzle.
class PuzzleReporter { //starts the output class 
public://print function in the public interface
    explicit PuzzleReporter(std::ostream& out) : out_(out) {} //remembers what stream to print to

    void printHeader(const std::string& fileName) const { //opens the banner function
        out_ << "==============================\n"//top banner
             << "File: " << fileName << "\n" //file name
             << "==============================\n"; //bottom banner
    } //end printHeader

    void printOriginal(const SudokuGrid& puzzle) const { //Shows the starting puzzle
        out_ << "Original puzzle:\n" << puzzle.toReadableString() << '\n'; //label, grid, then a blank line
    } //end printOriginal

    void printSolutions(const std::vector<SudokuGrid>& solutions) const { //opens printSolutions (will show the results)
        if (solutions.empty()) { //nothing was found
            out_ << "No solution found\n\n";//The wording (required) for no solution
            return;//nothing else to print
        }//ends if statement
        for (std::size_t i = 0; i < solutions.size(); ++i) { //goes though each solution
            out_ << "Solution " << (i + 1) << ":\n" << solutions[i].toReadableString() << '\n'; //starts at teh number 1, then prints the grid
        } //end for loop
        out_ << "Total solutions found: " << solutions.size() << "\n\n"; //finish the count
    } //End printSolutions

    // The header is printed by the caller, so this only prints the message.
    void printError(const std::string& message) const { //opens printError
        out_ << "ERROR: " << message << "\n\n"; //displays message followed by a blank line
    } // End printError

private:// data below is ONLY used in this class 
    std::ostream& out_; //the stream eveything is written too
}; //End of PuzzleReporter

// Coordinates reading, solving, and reporting for each file.
class PuzzleBatchRunner { //starts the PuzzleBatchRunner
public: //the constructor and runALL are teh public interface 
    explicit PuzzleBatchRunner(std::vector<std::string> fileNames)// constructor that recieves the list of files 
        : fileNames_(std::move(fileNames)), reporter_(std::cout) {} //will take the file list and targets the reporter at the console

    void runAll() { //Process every file in the list
        for (const std::string& fileName : fileNames_) runOne(fileName);//will handle one file after another
    }//end of runAll

private: //Declares as private
    //Handles a single file start to finish (edited)
    void runOne(const std::string& fileName) { //opens runONE
        reporter_.printHeader(fileName);  // the banner will print ONCE here (improvement from 2g)
        try { // printed once here for success and error cases
            SudokuGrid puzzle = reader_.read(fileName); //load the puzzle
            reporter_.printOriginal(puzzle); //displays puzzle before installing
            reporter_.printSolutions(solver_.findAllSolutions(puzzle)); // solve then print results 
        } catch (const PuzzleFileError& error) {//a file problem like a missing file or bad symbol
            reporter_.printError(error.what()); //displays the message and carry on with the next file
        } catch (const std::exception& error) { //any other unexpected problem 
            reporter_.printError(std::string("Unexpected failure: ") + error.what()); //error message instead of crash
        } //end of try
    } //end of run0ne

    std::vector<std::string> fileNames_; //list of files to process 
    PuzzleFileReader reader_; //converst files into grids
    SudokuSolver solver_; //looks for the solution
    PuzzleReporter reporter_; //prints output
}; //End of PuzzleBatchRunner

// main only supplies the file names; all logic lives in the classes above.
int main(int argc, char* argv[]) { //opens main
    std::vector<std::string> fileNames; //files to process 
    for (int i = 1; i < argc; ++i) fileNames.emplace_back(argv[i]); //On the command line use any typed file names
    if (fileNames.empty()) //Nothing typed will resultuses the 5 file assignments 
        fileNames = {"puzzle1.txt", "puzzle2.txt", "puzzle3.txt", "puzzle4.txt", "puzzle5.txt"}; //default list

    PuzzleBatchRunner runner(fileNames); // make the runnder with the final file
    runner.runAll(); //this will process every file
    return 0; //Tells program it's finished
} // End of main
